SET FOREIGN_KEY_CHECKS = 0;

-- ----------------------------
-- Records of peoples
-- ----------------------------
ON DUPLICATE KEY
UPDATE
    `document_type` = new.document_type,
    `document_number` = new.document_number,
    `first_name` = new.first_name,
    `last_name` = new.last_name,
    `birth_date` = new.birth_date,
    `gender` = new.gender,
    `address` = new.address,
    `phone` = new.phone,
    `email` = new.email;

SET FOREIGN_KEY_CHECKS = 1;